Type.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 35)\n    effect:addMod(xi.mod.STR, -1)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.MND, 3)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.ENMITY, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/plate_of_yahata-style_carp_sushi.lua"]={["Path"]="scripts/items/plate_of_yahata-style_carp_sushi.lua",["SHA256"]="ff19b073b0a82c9e5030d691e416e8a042bab3484f000794f4b0661f8d4f527c",["Text"]="-----------------------------------\n-- ID: 5186\n-- Item: plate_of_yahata-style_carp_sushi\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Accuracy % 11 (cap 56)\n-- HP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 56)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pluton_box.lua"]={["Path"]="scripts/items/pluton_box.lua",["SHA256"]="d17450bf615428d30583b5ed89869e5fb0638355c1dc063c04a0de6b299b85b1",["Text"]="-----------------------------------\n-- ID: 6183\n-- Pluton Box\n-- Breaks up a Pluton Box\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PLUTON, math.randomInt(15, 30) } })\nend\n\nreturn itemObject\n"},["scripts/items/pluton_case.lua"]={["Path"]="scripts/items/pluton_case.lua",["SHA256"]="803a5374ac36fd8a0d69aa43d06997e18b4d30db3864a07468d050cdf930f374",["Text"]="-----------------------------------\n-- ID: 6180\n-- Pluton Case\n-- Breaks up a Pluton Case\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PLUTON, math.randomInt(3, 15) } })\nend\n\nreturn itemObject\n"},["scripts/items/plutos_staff.lua"]={["Path"]="scripts/items/plutos_staff.lua",["SHA256"]="fe4a783edc437f173d008bbf258ce7db7fefc760873769bc2c0b0aef744f455f",["Text"]="-----------------------------------\n-- ID: 17560\n-- Item: Pluto's Staff\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/pogaca.lua"]={["Path"]="scripts/items/pogaca.lua",["SHA256"]="c4e23226a92fd91723372adddcd6c09979f609066bfacbfcd7b2c67fa8472b15",["Text"]="-----------------------------------\n-- ID: 5637\n-- Item: pogaca\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Lizard Killer +10\n-- Resist Paralyze +10\n-- HP Recovered While Healing 4\n-- MP Recovered While Healing 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.LIZARD_KILLER, 10)\n    effect:addMod(xi.mod.PARALYZERES, 10)\n    effect:addMod(xi.mod.HPHEAL, 4)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pogaca_+1.lua"]={["Path"]="scripts/items/pogaca_+1.lua",["SHA256"]="f63d00ba1af30343c315024b99530251ea60088150834c129d52140d9783f581",["Text"]="-----------------------------------\n-- ID: 5638\n-- Item: pogaca_+1\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Lizard Killer +12\n-- Resist Paralyze +12\n-- HP Recovered While Healing 6\n-- MP Recovered While Healing 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.LIZARD_KILLER, 12)\n    effect:addMod(xi.mod.PARALYZERES, 12)\n    effect:addMod(xi.mod.HPHEAL, 6)\n    effect:addMod(xi.mod.MPHEAL, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/poisona_ring.lua"]={["Path"]="scripts/items/poisona_ring.lua",["SHA256"]="7642151d5dcbf1fa2a24e6990e25bc10f109a539499c05d36409157f62084f51",["Text"]="-----------------------------------\n-- ID: 4148\n-- Item: Antidote\n-- Item Effect: This potion remedies poison.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.POISON) then\n        target:delStatusEffect(xi.effect.POISON)\n    end\nend\n\nreturn itemObject\n"}};
